// tools/meso5.test.js
//
// Mesocycle 5 — generated by /newplan from the meso 4 export (2026-11-16) and
// inserted with tools/insert-program.js. session-length.test.js already holds
// it to 50 modelled minutes in every week; this file pins the rest of what the
// block was designed to:
//
//   - the whole visit, warm-ups included, fits 60 minutes (the user's limit);
//   - every muscle starts at or above MEV, peaks inside MAV, never reaches MRV;
//   - the shoulder-cautious constraints carried over from meso 4;
//   - the analyzer fixes: rejected exercises are gone, calves clear MEV.
'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { loadApp } = require('./app-shim');
const LANDMARKS = require('./volume-landmarks.json');

const app = loadApp();
const MESO4_IDX = app.PROGRAMS.findIndex(p => p.id === 'meso4');
const MESO5 = app.PROGRAMS.find(p => p.id === 'meso5');
const sets = (ex, week) => app.setsForWeek(ex, week, MESO5);
const ACCUMULATION = [1, 2, 3, 4, 5, 6, 7];
const PEAK_WEEK = 7;

// ── Session pricing ─────────────────────────────────────────────────────────
// The same model as session-length.test.js (45 s / 32 s per compound /
// isolation set, each set's rest, 5 min prehab, superset rounds the way
// supersetStep() runs them, 20 s for the calibration set), plus warm-up, which
// that model leaves out: 3 min general, then 2 min of ramp-up sets before each
// compound. 50 modelled minutes + warm-up must come in at or under 60.
const WORK_COMPOUND = 45, WORK_ISOLATION = 32, PREHAB = 300, CALIBRATION = 20;
const WARMUP_GENERAL = 180, WARMUP_PER_COMPOUND = 120;
const work = ex => (ex.compound ? WORK_COMPOUND : WORK_ISOLATION);

function pairSeconds(a, b, week) {
  const na = sets(a, week), nb = sets(b, week), rounds = Math.min(na, nb);
  const T = app.SUPERSET_TRANSITION_SEC;
  const rest = Math.max(Math.max(a.rest, b.rest) - T - work(b), app.SUPERSET_MIN_REST_SEC);
  return rounds * (work(a) + T + work(b) + rest)
    + (na - rounds) * (work(a) + a.rest) + (nb - rounds) * (work(b) + b.rest);
}

function workingMinutes(day, week) {
  let s = (day.protocol ? PREHAB : 0)
    + (app.calibrationTarget(day, week - 1, MESO5) ? CALIBRATION : 0);
  const priced = new Set();
  for (const ex of day.exercises) {
    if (priced.has(ex)) continue;
    const partner = app.supersetPartner(day, ex);
    if (partner) { s += pairSeconds(ex, partner, week); priced.add(partner); }
    else s += sets(ex, week) * (work(ex) + ex.rest);
  }
  return s / 60;
}

const warmupMinutes = day =>
  (WARMUP_GENERAL + WARMUP_PER_COMPOUND * day.exercises.filter(e => e.compound).length) / 60;

// ── Volume ──────────────────────────────────────────────────────────────────
function weeklyVolume(week) {
  const v = Object.fromEntries(Object.keys(LANDMARKS).map(m => [m, 0]));
  for (const day of MESO5.days) {
    for (const ex of day.exercises) {
      for (const [m, credit] of Object.entries(ex.muscles)) v[m] += credit * sets(ex, week);
    }
  }
  return v;
}

// Erector volume is held low on purpose (RDL is the only axial loader), so it
// is exempt from the reach-MAV check — never from MEV or MRV.
const BELOW_MAV_BY_DESIGN = new Set(['spinal_erectors']);

test('meso5 follows meso4 as an 8-week, 5-day block with a final deload', () => {
  assert.ok(MESO5, 'meso5 is missing');
  assert.strictEqual(app.PROGRAMS.indexOf(MESO5), MESO4_IDX + 1);
  assert.strictEqual(MESO5.totalWeeks, 8);
  assert.strictEqual(MESO5.days.length, 5);
  assert.strictEqual(MESO5.weekPhases.length, 8);
  assert.ok(MESO5.weekPhases[7].deload, 'week 8 must be the deload');
  assert.ok(MESO5.weekPhases.slice(0, 7).every(p => !p.deload), 'only week 8 deloads');
});

for (let week = 1; week <= (MESO5 ? MESO5.totalWeeks : 0); week++) {
  test(`every meso5 visit in week ${week} fits 60 minutes including warm-ups`, () => {
    for (const day of MESO5.days) {
      const total = workingMinutes(day, week) + warmupMinutes(day);
      assert.ok(total <= 60,
        `meso5 ${day.id} (${day.title}) in week ${week}: ${total.toFixed(1)} min with warm-ups ` +
        `exceeds 60 — superset it or cut a redundant set, never shorten a rest`);
    }
  });
}

test('the meso5 deload is the shortest week of every day', () => {
  for (const day of MESO5.days) {
    const deload = workingMinutes(day, 8);
    for (const week of ACCUMULATION) {
      assert.ok(deload < workingMinutes(day, week), `${day.id} deload is not shorter than week ${week}`);
    }
  }
});

test('every meso5 muscle starts at or above MEV in week 1', () => {
  const v = weeklyVolume(1);
  for (const [m, l] of Object.entries(LANDMARKS)) {
    assert.ok(v[m] >= l.mev, `${m}: ${v[m]} sets in week 1, under MEV ${l.mev}`);
  }
});

test('no meso5 muscle reaches MRV in any week', () => {
  for (let week = 1; week <= MESO5.totalWeeks; week++) {
    const v = weeklyVolume(week);
    for (const [m, l] of Object.entries(LANDMARKS)) {
      assert.ok(v[m] < l.mrv, `${m}: ${v[m]} sets in week ${week}, at or over MRV ${l.mrv}`);
    }
  }
});

test('every meso5 muscle reaches MAV by the week-7 peak', () => {
  const v = weeklyVolume(PEAK_WEEK);
  for (const [m, l] of Object.entries(LANDMARKS)) {
    if (BELOW_MAV_BY_DESIGN.has(m)) continue;
    assert.ok(v[m] >= l.mavLow, `${m}: ${v[m]} sets at the peak, under MAV-low ${l.mavLow}`);
  }
});

test('meso5 volume never drops week over week across weeks 1–7', () => {
  for (let week = 2; week <= PEAK_WEEK; week++) {
    const prev = weeklyVolume(week - 1), cur = weeklyVolume(week);
    for (const m of Object.keys(LANDMARKS)) {
      assert.ok(cur[m] >= prev[m], `${m} drops from ${prev[m]} to ${cur[m]} in week ${week}`);
    }
  }
});

test('the meso5 deload cuts total volume to 40–60% of the peak', () => {
  const total = w => Object.values(weeklyVolume(w)).reduce((a, b) => a + b, 0);
  const ratio = total(8) / total(PEAK_WEEK);
  assert.ok(ratio >= 0.4 && ratio <= 0.6, `deload is ${(ratio * 100).toFixed(0)}% of the peak`);
});

test('biceps stay capped well under MRV — meso 2 hit 20.9/wk and the elbows paid for it', () => {
  for (let week = 1; week <= MESO5.totalWeeks; week++) {
    assert.ok(weeklyVolume(week).biceps <= 14, `biceps ${weeklyVolume(week).biceps} in week ${week}`);
  }
});

test('no meso5 session gives one muscle more than 8 direct sets', () => {
  for (const week of ACCUMULATION) {
    for (const day of MESO5.days) {
      const direct = {};
      for (const ex of day.exercises) {
        for (const [m, c] of Object.entries(ex.muscles)) if (c === 1) direct[m] = (direct[m] || 0) + sets(ex, week);
      }
      for (const [m, n] of Object.entries(direct)) {
        assert.ok(n <= 8, `${day.id} week ${week}: ${n} direct ${m} sets`);
      }
    }
  }
});

// ── Shoulder-cautious constraints (docs/training-evidence.md) ───────────────
const rpeTop = ex => Math.max(...String(ex.rpe).match(/\d+(\.\d+)?/g).map(Number));
const allExercises = () => MESO5.days.flatMap(d => d.exercises.map(ex => ({ day: d, ex })));

test('every meso5 push, pull and upper day runs the prehab protocol', () => {
  for (const day of MESO5.days) {
    if (/PUSH|PULL|UPPER/.test(day.title)) assert.strictEqual(day.protocol, true, `${day.id} has no prehab`);
  }
  assert.ok(MESO5.protocolItems.some(p => /pull-apart/i.test(p)));
  assert.ok(MESO5.protocolItems.some(p => /external rotation/i.test(p)));
  assert.ok(allExercises().some(({ ex }) => /face pull/i.test(ex.name)), 'face pulls are missing');
});

test('meso5 has no behind-the-neck work, and its pressing names a neutral grip or a fixed path', () => {
  for (const { ex } of allExercises()) {
    assert.ok(!/behind.the.neck/i.test(ex.name), ex.name);
  }
  const presses = allExercises().filter(({ ex }) =>
    ex.compound && /press/i.test(ex.name) && (ex.muscles.chest || ex.muscles.front_delt || ex.muscles.triceps));
  assert.ok(presses.length >= 4);
  for (const { ex } of presses) {
    assert.ok(/neutral|machine|incline db/i.test(ex.name) || /neutral/i.test(ex.note),
      `${ex.name} names no neutral grip or machine path`);
  }
});

test('side delt, rear delt and compound work in meso5 never prescribes 0 RIR', () => {
  for (const { ex } of allExercises()) {
    const delt = ex.muscles.side_delt === 1 || ex.muscles.rear_delt === 1;
    if (delt || ex.compound) assert.ok(rpeTop(ex) <= 9, `${ex.name} prescribes RPE ${ex.rpe}`);
  }
});

test('the RDL is the only meso5 exercise loading the spinal erectors', () => {
  const loaders = allExercises().filter(({ ex }) => ex.muscles.spinal_erectors);
  assert.deepStrictEqual(loaders.map(({ ex }) => ex.id), ['m5_rdl']);
});

test('no meso5 superset puts the grip-heavy shrug next to a pull', () => {
  for (const day of MESO5.days) {
    for (const ex of day.exercises) {
      if (!/shrug/i.test(ex.name)) continue;
      const partner = app.supersetPartner(day, ex);
      assert.ok(!partner || !(partner.muscles.lats || partner.muscles.upper_back),
        `${ex.name} is paired with ${partner && partner.name}`);
    }
  }
});

// ── What the meso 4 analysis asked for ──────────────────────────────────────
test('meso5 drops the exercises meso 4 rejected (walking lunge 52%, suitcase carry 41% skipped)', () => {
  for (const { ex } of allExercises()) {
    assert.ok(!/walking lunge|suitcase carry/i.test(ex.name), `${ex.name} is back`);
  }
});

test('meso5 promotes the DB row the user swapped to in 5 of 8 meso 4 weeks', () => {
  assert.ok(allExercises().some(({ ex }) => ex.id === 'm5_db_row'));
});
